529	// 原始正文字节的无损文本表示：先尝试严格 UTF-8；失败则用 base64 承载任意字节。
530	// 记录的是原始字节而非解析后的 JSON，避免任何信息损失。
531	function encodeBodyLosslessly(body: Buffer): { encoding: 'utf-8' | 'base64'; content: string } {
532	  try {
533	    const text = new TextDecoder('utf-8', { fatal: true }).decode(body);
534	    return { encoding: 'utf-8', content: text };
535	  } catch {
536	    return { encoding: 'base64', content: body.toString('base64') };
537	  }
538	}
