651	// 返回 null 表示校验通过；否则为可直接序列化的 400 差异报告
652	function validateRequestBody(
653	  req: http.IncomingMessage,
654	  body: Buffer,
655	  rule: BodyRule,
656	): BodyReport | null {
657	  const contentType = req.headers['content-type'];
658	  const mediaType =
659	    typeof contentType === 'string' ? contentType.split(';', 1)[0].trim().toLowerCase() : '';
660	  if (mediaType !== 'application/json') {
661	    return parseFailure(
662	      typeof contentType === 'string'
663	        ? `媒体类型不符：期望 application/json（可带参数、忽略大小写），收到 "${contentType}"`
664	        : '缺少 Content-Type 头：期望 application/json（可带参数、忽略大小写）',
665	    );
666	  }
667	
668	  if (body.length === 0) {
669	    return parseFailure('请求正文为空，无法解析为 JSON');
670	  }
671	
672	  let text: string;
673	  try {
674	    text = new TextDecoder('utf-8', { fatal: true }).decode(body);
675	  } catch {
676	    return parseFailure('请求正文不是合法的 UTF-8 编码');
677	  }
678	
679	  let parsed: unknown;
680	  try {
681	    parsed = JSON.parse(text);
682	  } catch (e) {
683	    return parseFailure(`请求正文不是合法 JSON：${describeError(e)}`);
684	  }
685	
686	  const problems: StructureProblem[] = [];
687	  checkRule(rule, parsed, '', problems);
688	  if (problems.length > 0) {
689	    return {
690	      error: 'invalid_request_body',
691	      stage: 'structure',
692	      message: `请求正文与接口约定存在 ${problems.length} 处差异`,
693	      problems,
694	    };
695	  }
696	  return null;
697	}
