970	// 旧接口被旧配置接受的一个请求样本（用于“接口已删除”反例）
971	function acceptedRequestExample(endpoint: EndpointSpec): ReportExample {
972	  if (endpoint.bodyRule) {
973	    return {
974	      method: endpoint.method,
975	      path: endpoint.path,
976	      headers: { 'Content-Type': 'application/json' },
977	      body: JSON.stringify(sampleValue(endpoint.bodyRule)),
978	    };
979	  }
980	  return { method: endpoint.method, path: endpoint.path, headers: {}, body: '' };
981	}
982	
983	function compareEndpoint(oldEp: EndpointSpec, newEp: EndpointSpec | undefined): EndpointReport {
984	  const base = { method: oldEp.method, path: oldEp.path };
985	
986	  if (!newEp) {
987	    return {
988	      ...base,
989	      compatible: false,
990	      reasons: [
991	        { message: '新配置中不存在该接口：按 方法 + 字面路径 匹配不到，旧客户端的调用将得到 404' },
992	      ],
993	      example: acceptedRequestExample(oldEp),
994	    };
995	  }
996	
997	  if (!oldEp.bodyRule && !newEp.bodyRule) {
998	    return { ...base, compatible: true, reasons: [] };
999	  }
1000	
1001	  if (!oldEp.bodyRule && newEp.bodyRule) {
1002	    // 旧版允许任意媒体类型与正文；新版启用校验即存在被拒绝的旧请求
1003	    return {
1004	      ...base,
1005	      compatible: false,
1006	      reasons: [
1007	        {
1008	          pointer: '',
1009	          message: '旧接口不校验请求正文（任意媒体类型与正文均可），新接口启用了 requestBody 正文校验',
1010	        },
1011	      ],
1012	      example: {
1013	        ...base,
1014	        headers: { 'Content-Type': 'application/json' },
1015	        body: JSON.stringify(violateValue(newEp.bodyRule)),
1016	      },
1017	    };
1018	  }
1019	
1020	  if (oldEp.bodyRule && !newEp.bodyRule) {
1021	    return { ...base, compatible: true, reasons: [] }; // 移除规则更宽松
1022	  }
1023	
1024	  const violations: BodyViolation[] = [];
1025	  collectViolations(oldEp.bodyRule as BodyRule, newEp.bodyRule as BodyRule, '', violations);
1026	  if (violations.length === 0) {
1027	    return { ...base, compatible: true, reasons: [] };
1028	  }
1029	  return {
1030	    ...base,
1031	    compatible: false,
1032	    reasons: violations.map((v) => ({ pointer: v.pointer, message: v.message })),
1033	    example: {
1034	      ...base,
1035	      headers: { 'Content-Type': 'application/json' },
1036	      body: JSON.stringify(violations[0].value),
1037	    },
1038	  };
1039	}
