1145	// 转换过程中的规范化规则：与 BodyRule 同构，但 object 的必填名集合单独保存，
1146	// 便于 allOf 交集计算；输出时再展开为场景规则 JSON。
1147	type NormRule =
1148	  | {
1149	      readonly kind: 'object';
1150	      readonly props: ReadonlyMap<string, NormRule>;
1151	      readonly required: ReadonlySet<string>;
1152	      readonly addl: boolean;
1153	    }
1154	  | { readonly kind: 'array'; readonly items: NormRule }
1155	  | { readonly kind: 'string' | 'number' | 'integer' | 'boolean' };
1156	
1157	type NormObject = Extract<NormRule, { kind: 'object' }>;
1158	
1159	interface ImportCtx {
1160	  // 整份 OpenAPI 文档（$ref 解析的根）
1161	  readonly doc: unknown;
1162	  readonly file: string;
1163	}
1164	
1165	function importErrorMessage(ctx: ImportCtx, where: string, message: string): string {
1166	  return where === ''
1167	    ? `OpenAPI 文件 ${ctx.file}：${message}`
1168	    : `OpenAPI 文件 ${ctx.file} 的 ${where}：${message}`;
1169	}
1170	
1171	function importFail(ctx: ImportCtx, where: string, message: string): never {
1172	  throw new ImportError(importErrorMessage(ctx, where, message));
1173	}
1174	
1175	const OPENAPI_ANNOTATION_KEYS: ReadonlySet<string> = new Set([
1176	  'title',
1177	  'description',
1178	  'example',
1179	  'nullable',
1180	]);
1181	
1182	const OPENAPI_SCALAR_TYPES: ReadonlySet<string> = new Set([
1183	  'string',
1184	  'number',
1185	  'integer',
1186	  'boolean',
1187	]);
1188	
1189	function hasOwnKey(value: object, key: string): boolean {
1190	  return Object.prototype.hasOwnProperty.call(value, key);
1191	}
