1221	// 解析一层 $ref：node 是“只含 $ref 的引用节点”时返回目标与新的位置/引用链，
1222	// 否则返回 null。外部引用、非法指针、目标缺失、循环引用都在此拒绝。
1223	function dereference(
1224	  node: Record<string, unknown>,
1225	  ctx: ImportCtx,
1226	  where: string,
1227	  refChain: readonly string[],
1228	): { target: unknown; where: string; refChain: readonly string[] } | null {
1229	  if (!hasOwnKey(node, '$ref')) {
1230	    return null;
1231	  }
1232	  if (Object.keys(node).length !== 1) {
1233	    importFail(ctx, where, '含 $ref 的引用节点不得包含其他字段（只允许 "$ref"）');
1234	  }
1235	  const ref = node.$ref;
1236	  if (typeof ref !== 'string' || !ref.startsWith('#')) {
1237	    importFail(
1238	      ctx,
1239	      where,
1240	      `仅支持本文件内 $ref（以 "#" 开头的 JSON Pointer），收到 ${JSON.stringify(ref)}`,
1241	    );
1242	  }
1243	  if (refChain.includes(ref as string)) {
1244	    importFail(ctx, where, `循环 $ref 引用：${[...refChain, ref].join(' -> ')}`);
1245	  }
1246	  const fragment = (ref as string).slice(1);
1247	  let target: unknown = ctx.doc;
1248	  if (fragment !== '') {
1249	    if (!fragment.startsWith('/')) {
1250	      importFail(ctx, where, `$ref "${ref as string}" 不是合法的 JSON Pointer 片段`);
1251	    }
1252	    const segments = fragment
1253	      .slice(1)
1254	      .split('/')
1255	      .map((seg) => unescapeRefSegment(seg, ref as string, ctx, where));
1256	    let traversed = '#';
1257	    for (const segment of segments) {
1258	      traversed = `${traversed}/${escapePointerSegment(segment)}`;
1259	      if (Array.isArray(target)) {
1260	        if (!/^(0|[1-9]\d*)$/.test(segment) || Number(segment) >= target.length) {
1261	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 超出数组范围`);
1262	        }
1263	        target = target[Number(segment)];
1264	      } else if (isPlainObject(target)) {
1265	        if (!hasOwnKey(target, segment)) {
1266	          importFail(ctx, where, `$ref "${ref as string}" 的目标不存在：${traversed} 缺失`);
1267	        }
1268	        target = target[segment];
1269	      } else {
1270	        importFail(ctx, where, `$ref "${ref as string}" 无法继续解析：${traversed} 不是对象或数组`);
1271	      }
1272	    }
1273	  }
1274	  return { target, where: `${where} -> ${ref as string}`, refChain: [...refChain, ref as string] };
1275	}
