1277	// schema（或引用链尽头的 schema）-> 规范化规则
1278	function schemaToNorm(
1279	  rawNode: unknown,
1280	  ctx: ImportCtx,
1281	  where: string,
1282	  refChain: readonly string[],
1283	): NormRule {
1284	  let node = rawNode;
1285	  let nodeWhere = where;
1286	  let chain = refChain;
1287	  // 引用节点可以层层指向另一个引用节点
1288	  for (;;) {
1289	    if (!isPlainObject(node)) {
1290	      importFail(ctx, nodeWhere, 'schema 必须是对象');
1291	    }
1292	    const ref = dereference(node, ctx, nodeWhere, chain);
1293	    if (!ref) {
1294	      break;
1295	    }
1296	    node = ref.target;
1297	    nodeWhere = ref.where;
1298	    chain = ref.refChain;
1299	  }
1300	  const n = node as Record<string, unknown>;
1301	
1302	  // nullable 仅允许 false（等同不声明，忽略）；true 属于非法值
1303	  if (hasOwnKey(n, 'nullable') && n.nullable !== false) {
1304	    importFail(ctx, `${nodeWhere}.nullable`, `仅支持 false（或不声明），收到 ${JSON.stringify(n.nullable)}`);
1305	  }
1306	
1307	  if (hasOwnKey(n, 'allOf')) {
1308	    for (const key of Object.keys(n)) {
1309	      if (key !== 'allOf' && !OPENAPI_ANNOTATION_KEYS.has(key)) {
1310	        importFail(
1311	          ctx,
1312	          nodeWhere,
1313	          `组合节点仅允许 allOf 及注释（title/description/example/nullable），含未支持的关键字 "${key}"`,
1314	        );
1315	      }
1316	    }
1317	    const list = n.allOf;
1318	    if (!Array.isArray(list) || list.length === 0) {
1319	      importFail(ctx, `${nodeWhere}.allOf`, '必须是非空数组');
1320	    }
1321	    const branches = (list as unknown[]).map((branch, i) =>
1322	      schemaToNorm(branch, ctx, `${nodeWhere}.allOf[${i}]`, chain),
1323	    );
1324	    for (let i = 0; i < branches.length; i += 1) {
1325	      const branch = branches[i] as NormRule;
1326	      if (branch.kind !== 'object') {
1327	        importFail(
1328	          ctx,
1329	          `${nodeWhere}.allOf[${i}]`,
1330	          `仅支持纯对象 allOf 组合，该分支最终类型为 ${branch.kind}`,
1331	        );
1332	      }
1333	    }
1334	    return mergeObjectNorms(branches as NormObject[], ctx, nodeWhere);
1335	  }
1336	
1337	  const type = n.type;
1338	  if (
1339	    typeof type !== 'string' ||
1340	    (type !== 'object' && type !== 'array' && !OPENAPI_SCALAR_TYPES.has(type))
1341	  ) {
1342	    importFail(
1343	      ctx,
1344	      `${nodeWhere}.type`,
1345	      `必须是 "object" | "array" | "string" | "number" | "integer" | "boolean"，收到 ${JSON.stringify(n.type)}`,
1346	    );
1347	  }
1348	  const structural: readonly string[] =
1349	    type === 'object'
1350	      ? ['properties', 'required', 'additionalProperties']
1351	      : type === 'array'
1352	        ? ['items']
1353	        : [];
1354	  for (const key of Object.keys(n)) {
1355	    if (key !== 'type' && !OPENAPI_ANNOTATION_KEYS.has(key) && !structural.includes(key)) {
1356	      importFail(ctx, nodeWhere, `含未支持的关键字 "${key}"`);
1357	    }
1358	  }
1359	
1360	  if (type === 'array') {
1361	    if (!hasOwnKey(n, 'items')) {
1362	      importFail(ctx, `${nodeWhere}.items`, '数组 schema 必须声明元素规则 items');
1363	    }
1364	    return { kind: 'array', items: schemaToNorm(n.items, ctx, `${nodeWhere}.items`, chain) };
1365	  }
1366	
1367	  if (type === 'object') {
1368	    const propsRaw = n.properties;
1369	    if (propsRaw !== undefined && !isPlainObject(propsRaw)) {
1370	      importFail(ctx, `${nodeWhere}.properties`, '必须是对象（字段名 -> schema）');
1371	    }
1372	    const reqRaw = n.required;
1373	    const requiredList: string[] = [];
1374	    if (reqRaw !== undefined) {
1375	      if (!Array.isArray(reqRaw)) {
1376	        importFail(ctx, `${nodeWhere}.required`, '必须是字符串数组');
1377	      }
1378	      for (let i = 0; i < (reqRaw as unknown[]).length; i += 1) {
1379	        const item = (reqRaw as unknown[])[i];
1380	        if (typeof item !== 'string') {
1381	          importFail(ctx, `${nodeWhere}.required[${i}]`, `必须是字符串，收到 ${JSON.stringify(item)}`);
1382	        }
1383	        if (requiredList.includes(item as string)) {
1384	          importFail(ctx, `${nodeWhere}.required`, `含重复项 ${JSON.stringify(item)}`);
1385	        }
1386	        requiredList.push(item as string);
1387	      }
1388	    }
1389	    const props = new Map<string, NormRule>();
1390	    if (propsRaw !== undefined) {
1391	      for (const [name, sub] of Object.entries(propsRaw as Record<string, unknown>)) {
1392	        props.set(
1393	          name,
1394	          schemaToNorm(sub, ctx, `${nodeWhere}.properties[${JSON.stringify(name)}]`, chain),
1395	        );
1396	      }
1397	    }
1398	    for (const name of requiredList) {
1399	      if (!props.has(name)) {
