1413	  }
1414	
1415	  return { kind: type as 'string' | 'number' | 'integer' | 'boolean' };
1416	}
1417	
1418	// 两个规范化规则的交集；交集为空抛 EmptyIntersection，现有规则种类无法表达
1419	// 时抛 ImportError。
1420	function intersectNorms(a: NormRule, b: NormRule, ctx: ImportCtx, where: string): NormRule {
1421	  if (a.kind === 'object' && b.kind === 'object') {
1422	    return mergeObjectNorms([a, b], ctx, where);
1423	  }
1424	  if (a.kind === 'array' && b.kind === 'array') {
1425	    try {
1426	      return { kind: 'array', items: intersectNorms(a.items, b.items, ctx, `${where}.items`) };
1427	    } catch (e) {
1428	      if (e instanceof EmptyIntersection) {
1429	        throw new ImportError(
1430	          importErrorMessage(
1431	            ctx,
1432	            where,
1433	            `数组元素规则交集为空（${e.message}），交集结果仅含空数组，现有规则种类无法表达`,
1434	          ),
1435	        );
1436	      }
1437	      throw e;
1438	    }
1439	  }
1440	  if (a.kind === 'object' || a.kind === 'array' || b.kind === 'object' || b.kind === 'array') {
1441	    throw new EmptyIntersection(`类型 ${a.kind} 与 ${b.kind} 没有共同接受的值`);
1442	  }
1443	  if (a.kind === b.kind) {
1444	    return a;
1445	  }
1446	  // number 与 integer 相交取 integer；其余标量组合交集为空
1447	  if (
1448	    (a.kind === 'number' && b.kind === 'integer') ||
1449	    (a.kind === 'integer' && b.kind === 'number')
1450	  ) {
1451	    return { kind: 'integer' };
1452	  }
1453	  throw new EmptyIntersection(`类型 ${a.kind} 与 ${b.kind} 没有共同接受的值`);
1454	}
1455	
1456	// 纯对象 allOf 的交集：结果接受集合 = 各分支接受集合的交集。
1457	// - 字段可出现的条件：在每个分支中都已声明，或该分支允许额外字段；
1458	//   必填字段若被某分支禁止出现，则交集为空；
1459	// - 同名字段递归相交（number∩integer 取 integer）；必填取并集；
1460	// - 结果的 additionalProperties 为各分支的合取（任一分支拒绝则拒绝）；
1461	// - 可选字段交集为空且结果拒绝额外字段时，不声明该字段即“禁止出现”，
1462	//   集合语义不变；结果允许额外字段时无法表达，拒绝。
1463	function mergeObjectNorms(
1464	  branches: readonly NormObject[],
1465	  ctx: ImportCtx,
1466	  where: string,
1467	): NormObject {
1468	  const addl = branches.every((b) => b.addl);
1469	  const props = new Map<string, NormRule>();
1470	  const required = new Set<string>();
1471	
1472	  const names: string[] = [];
1473	  const seen = new Set<string>();
1474	  for (const branch of branches) {
1475	    for (const name of branch.props.keys()) {
1476	      if (!seen.has(name)) {
1477	        seen.add(name);
1478	        names.push(name);
1479	      }
1480	    }
1481	  }
1482	
1483	  for (const name of names) {
1484	    const fieldWhere = `${where}.properties[${JSON.stringify(name)}]`;
1485	    const isRequired = branches.some((b) => b.required.has(name));
1486	    const permitted = branches.every((b) => b.props.has(name) || b.addl);
1487	    if (!permitted) {
1488	      // 该字段在交集中禁止出现：不声明即可表达（此时必有分支 addl=false，
1489	      // 结果 addl 必为 false）
1490	      if (isRequired) {
1491	        throw new EmptyIntersection(
1492	          `字段 ${JSON.stringify(name)} 在部分分支中为必填，但被另一分支禁止出现（未声明且 additionalProperties 为 false），交集为空`,
1493	        );
1494	      }
1495	      continue;
1496	    }
1497	    let merged: NormRule | undefined;
1498	    for (const branch of branches) {
1499	      const sub = branch.props.get(name);
1500	      if (sub === undefined) {
1501	        continue;
1502	      }
1503	      if (merged === undefined) {
1504	        merged = sub;
1505	        continue;
1506	      }
1507	      try {
1508	        merged = intersectNorms(merged, sub, ctx, fieldWhere);
1509	      } catch (e) {
1510	        if (e instanceof EmptyIntersection) {
1511	          if (isRequired) {
1512	            throw new EmptyIntersection(
1513	              `必填字段 ${JSON.stringify(name)} 的各分支规则交集为空：${e.message}`,
1514	            );
1515	          }
1516	          if (addl) {
1517	            throw new ImportError(
1518	              importErrorMessage(
1519	                ctx,
1520	                fieldWhere,
1521	                `各分支规则交集为空（${e.message}），且所有分支都允许额外字段，现有规则种类无法表达“禁止该字段出现”`,
1522	              ),
1523	            );
1524	          }
1525	          // 可选字段交集为空且结果拒绝额外字段：不声明该字段即“禁止出现”
1526	          merged = undefined;
1527	          break;
1528	        }
1529	        throw e;
1530	      }
1531	    }
1532	    if (merged !== undefined) {
1533	      props.set(name, merged);
1534	      if (isRequired) {
1535	        required.add(name);
1536	      }
1537	    }
1538	  }
1539	
1540	  return { kind: 'object', props, required, addl };
1541	}
