1543	// 规范化规则 -> 场景规则 JSON（object 显式写出 fields 与 additionalProperties；
1544	// 字段名可能是 ""/"__proto__"/含斜杠波浪号，一律用无原型对象按自有字段构造）
1545	function normToRuleJson(rule: NormRule): Record<string, unknown> {
1546	  switch (rule.kind) {
1547	    case 'object': {
1548	      const fields: Record<string, unknown> = Object.create(null);
1549	      for (const [name, sub] of rule.props) {
1550	        const subJson = normToRuleJson(sub);
1551	        fields[name] = rule.required.has(name) ? { ...subJson, required: true } : subJson;
1552	      }
1553	      return { type: 'object', fields, additionalProperties: rule.addl };
1554	    }
1555	    case 'array':
1556	      return { type: 'array', items: normToRuleJson(rule.items) };
1557	    default:
1558	      return { type: rule.kind };
1559	  }
1560	}
