1562	// 转换一个操作的 requestBody；操作未声明 requestBody 时返回 undefined
1563	// （POST 移除接口旧规则；GET 本就不允许携带规则）。
1564	function importOperationBodyRule(
1565	  operation: Record<string, unknown>,
1566	  method: HttpMethod,
1567	  ctx: ImportCtx,
1568	  opWhere: string,
1569	): unknown {
1570	  if (!hasOwnKey(operation, 'requestBody')) {
1571	    return undefined;
1572	  }
1573	  const rbWhere = `${opWhere}.requestBody`;
1574	  if (method === 'GET') {
1575	    importFail(ctx, rbWhere, 'GET 操作不允许声明请求正文');
1576	  }
1577	  // requestBody 本身也可以是本文件内 $ref（可层层引用）
1578	  let node: unknown = operation.requestBody;
1579	  let nodeWhere = rbWhere;
1580	  let chain: readonly string[] = [];
1581	  for (;;) {
1582	    if (!isPlainObject(node)) {
1583	      importFail(ctx, nodeWhere, '必须是对象');
1584	    }
1585	    const ref = dereference(node, ctx, nodeWhere, chain);
1586	    if (!ref) {
1587	      break;
1588	    }
1589	    node = ref.target;
1590	    nodeWhere = ref.where;
1591	    chain = ref.refChain;
1592	  }
1593	  const rb = node as Record<string, unknown>;
1594	  for (const key of Object.keys(rb)) {
1595	    if (key !== 'required' && key !== 'content' && key !== 'description') {
1596	      importFail(ctx, nodeWhere, `含未支持的字段 "${key}"`);
1597	    }
1598	  }
1599	  if (rb.required !== true) {
1600	    importFail(
1601	      ctx,
1602	      `${nodeWhere}.required`,
1603	      `导入的请求正文约定一律按必填处理，required 必须为 true，收到 ${JSON.stringify(rb.required)}`,
1604	    );
1605	  }
1606	  const content = rb.content;
1607	  if (!isPlainObject(content)) {
1608	    importFail(ctx, `${nodeWhere}.content`, '必须是对象且仅含 "application/json" 一种媒体类型');
1609	  }
1610	  const mediaTypes = Object.keys(content as Record<string, unknown>);
1611	  if (mediaTypes.length !== 1 || mediaTypes[0] !== 'application/json') {
1612	    importFail(
1613	      ctx,
1614	      `${nodeWhere}.content`,
1615	      `仅允许且必须包含 "application/json" 一种媒体类型，收到 ${JSON.stringify(mediaTypes)}`,
1616	    );
1617	  }
1618	  const media = (content as Record<string, unknown>)['application/json'];
1619	  const mediaWhere = `${nodeWhere}.content["application/json"]`;
1620	  if (!isPlainObject(media)) {
1621	    importFail(ctx, mediaWhere, '必须是对象');
1622	  }
1623	  for (const key of Object.keys(media as Record<string, unknown>)) {
1624	    if (key !== 'schema' && key !== 'example' && key !== 'examples') {
1625	      importFail(ctx, mediaWhere, `含未支持的字段 "${key}"`);
1626	    }
1627	  }
1628	  if (!hasOwnKey(media as Record<string, unknown>, 'schema')) {
1629	    importFail(ctx, mediaWhere, '缺少 schema');
1630	  }
1631	  const norm = schemaToNorm(
1632	    (media as Record<string, unknown>).schema,
1633	    ctx,
1634	    `${mediaWhere}.schema`,
1635	    [],
1636	  );
1637	  return normToRuleJson(norm);
1638	}
