1640	// 为场景每个接口选择文档操作并转换；任一失败抛 ImportError，不产生部分输出。
1641	// 未被选中的操作与不可达定义不参与转换。
1642	function importEndpoints(sceneRaw: unknown, ctx: ImportCtx): unknown[] {
1643	  const doc = ctx.doc;
1644	  if (!isPlainObject(doc)) {
1645	    importFail(ctx, '', '顶层必须是 JSON 对象');
1646	  }
1647	  const version = (doc as Record<string, unknown>).openapi;
1648	  if (typeof version !== 'string' || !/^3\.0\.\d+/.test(version)) {
1649	    importFail(ctx, 'openapi', `仅支持 OpenAPI 3.0.x，收到 ${JSON.stringify(version)}`);
1650	  }
1651	  const paths = (doc as Record<string, unknown>).paths;
1652	  if (!isPlainObject(paths)) {
1653	    importFail(ctx, 'paths', '必须是对象（路径 -> 路径项）');
1654	  }
1655	  const endpoints = (sceneRaw as { endpoints: unknown[] }).endpoints;
1656	  return endpoints.map((epRaw, index) => {
1657	    const ep = epRaw as { method: HttpMethod; path: string; responses: unknown };
1658	    const label = `场景接口 endpoints[${index}]（${ep.method} ${ep.path}）`;
1659	    if (!hasOwnKey(paths, ep.path)) {
1660	      importFail(ctx, 'paths', `${label} 缺少对应操作：路径 ${JSON.stringify(ep.path)} 不存在`);
1661	    }
1662	    const pathItem = (paths as Record<string, unknown>)[ep.path];
1663	    const pathWhere = `paths[${JSON.stringify(ep.path)}]`;
1664	    if (!isPlainObject(pathItem)) {
1665	      importFail(ctx, pathWhere, '必须是对象');
1666	    }
1667	    const methodKey = ep.method.toLowerCase();
1668	    if (!hasOwnKey(pathItem, methodKey)) {
1669	      importFail(ctx, pathWhere, `${label} 缺少对应操作：${methodKey} 操作不存在`);
1670	    }
1671	    const operation = (pathItem as Record<string, unknown>)[methodKey];
1672	    const opWhere = `${pathWhere}.${methodKey}`;
1673	    if (!isPlainObject(operation)) {
1674	      importFail(ctx, opWhere, '必须是对象');
1675	    }
1676	    const rule = importOperationBodyRule(operation, ep.method, ctx, opWhere);
1677	    // 仅替换 requestBody：保留接口顺序与 responses 原文
1678	    const out: { method: string; path: string; requestBody?: unknown; responses: unknown } = {
1679	      method: ep.method,
1680	      path: ep.path,
1681	      responses: ep.responses,
1682	    };
1683	    if (rule !== undefined) {
1684	      out.requestBody = rule;
1685	    }
1686	    return out;
1687	  });
1688	}
