1748	      const next = await loadStateFromFile(configFile, activeState.version + 1);
1749	      activeState = next; // 单次同步赋值：请求不可能看到混合配置
1750	      return { ok: true, version: activeState.version };
1751	    } catch (e) {
1752	      // 不修改配置/版本，不重置序列；旧场景的正常消费继续
1753	      return { ok: false, version: activeState.version, error: describeError(e) };
1754	    }
1755	  });
1756	  // 失败也不能打断后续 reload 的排队
1757	  reloadChain = job.then(
1758	    () => undefined,
1759	    () => undefined,
1760	  );
1761	  return job;
1762	}
