1764	function writeResponse(
1765	  res: http.ServerResponse,
1766	  status: number,
1767	  headers: { readonly [name: string]: string },
1768	  body: string,
1769	): void {
1770	  try {
1771	    res.writeHead(status, headers);
1772	    res.end(body === '' ? undefined : body);
1773	  } catch {
1774	    // 预留之后客户端可能已断开：响应仍计为已消费，发送失败仅静默忽略
1775	  }
