1813	// ---------------------------------------------------------------------------
1814	// 计划响应快照与写出跟踪
1815	// ---------------------------------------------------------------------------
1816	//
1817	// 业务/框架响应在“请求完整接收”那一刻就构造为一份计划快照：
1818	// 记录中保存的状态/应用层头/正文与随后真正写上线的字节共用同一份数据，
1819	// reload 不影响在途请求（它持有的是快照而非当前配置）。
1820	
1821	function freezeHeaders(headers: { [name: string]: string }): { readonly [name: string]: string } {
1822	  return Object.freeze(headers);
1823	}
