1825	// 场景响应的应用层头：配置头 + 服务器填写的准确版本头（+ 必要时的默认 Content-Type）。
1826	// 不含 Content-Length/Connection/Date/Transfer-Encoding 等传输层自动头。
1827	function buildSceneHeaders(
1828	  item: ResponseSpec,
1829	  version: number,
1830	): { readonly [name: string]: string } {
1831	  const headers = versionHeaders(version);
1832	  let contentTypeSet = false;
1833	  for (const [name, value] of Object.entries(item.headers)) {
1834	    const lower = name.toLowerCase();
1835	    // 版本头由服务器填写且必须唯一准确：配置中的同名头（含大小写变体）可加载，发送时忽略其值
1836	    if (lower === VERSION_HEADER.toLowerCase()) {
1837	      continue;
1838	    }
1839	    if (lower === 'content-type') {
1840	      contentTypeSet = true;
1841	    }
1842	    headers[name] = value;
1843	  }
1844	  // 文本正文的默认内容类型；配置显式给出时不覆盖
1845	  if (!contentTypeSet && item.body !== '') {
1846	    headers['Content-Type'] = 'text/plain; charset=utf-8';
1847	  }
1848	  return freezeHeaders(headers);
1849	}
