1874	// 按计划快照写出；writeHead/end 在已断开套接字上抛错时标记为中断（消费已成立）。
1875	function writePlanned(
1876	  res: http.ServerResponse,
1877	  planned: PlannedResponseSnapshot,
1878	  recordId: number,
1879	): void {
1880	  try {
1881	    res.writeHead(planned.status, { ...planned.headers });
