1888	// 挂载一次写出生命周期跟踪。每个被记录的请求恰好回复一次，故在接收完成后立即挂载：
1889	// 延迟期间断开也能标为中断；'sent' 为终态，随后连接正常关闭不回退。
1890	function attachDeliveryTracking(res: http.ServerResponse, recordId: number): void {
1891	  let settled = false;
1892	  const settle = (status: DeliveryStatus): void => {
1893	    if (settled) {
1894	      return;
1895	    }
1896	    settled = true;
1897	    requestLog.markDelivered(recordId, status);
1898	  };
1899	  res.once('finish', () => settle('sent'));
1900	  res.once('close', () => settle(res.writableFinished ? 'sent' : 'interrupted'));
1901	  res.once('error', () => settle('interrupted'));
1902	}
