1904	// 延迟结束才按接收时的计划快照发送；即便客户端提前断开也继续计时（消费在预留时已成立）
1905	function schedulePlannedResponse(
1906	  res: http.ServerResponse,
1907	  planned: PlannedResponseSnapshot,
1908	  delay: number,
1909	  recordId: number,
1910	): void {
1911	  const timer = setTimeout(() => {
1912	    pendingTimers.delete(timer);
1913	    writePlanned(res, planned, recordId);
1914	  }, delay);
1915	  pendingTimers.add(timer);
1916	}
