1918	type BodyOutcome = 'received' | 'aborted' | 'too-large';
1919	
1920	interface ReceivedBody {
1921	  readonly outcome: BodyOutcome;
1922	  // 仅在 outcome 为 'received' 时有意义（完整请求体）
1923	  readonly body: Buffer;
1924	}
1925	
1926	// 完整接收请求体；未完整接收即断开返回 'aborted'（调用方不得推进序列）
1927	function receiveBody(req: http.IncomingMessage, res: http.ServerResponse): Promise<ReceivedBody> {
1928	  return new Promise((resolve) => {
1929	    let settled = false;
1930	    let size = 0;
1931	    const chunks: Buffer[] = [];
1932	    const finish = (outcome: BodyOutcome): void => {
1933	      if (!settled) {
1934	        settled = true;
1935	        resolve({ outcome, body: outcome === 'received' ? Buffer.concat(chunks) : Buffer.alloc(0) });
1936	      }
1937	    };
1938	    req.on('data', (chunk: Buffer) => {
1939	      size += chunk.byteLength;
1940	      if (size > MAX_BODY_BYTES) {
1941	        finish('too-large');
1942	        writeResponse(
1943	          res,
1944	          413,
1945	          versionHeaders(activeState.version, {
1946	            'Content-Type': 'text/plain; charset=utf-8',
1947	          }),
1948	          'payload too large\n',
1949	        );
1950	        // 等 413 刷出后再断开，避免客户端收不到响应
1951	        res.once('finish', () => req.socket.destroy());
1952	        return;
1953	      }
1954	      chunks.push(chunk);
1955	    });
1956	    req.on('end', () => finish('received'));
1957	    req.on('error', () => finish('aborted'));
1958	    req.on('aborted', () => finish('aborted'));
1959	    res.on('close', () => finish('aborted'));
1960	  });
1961	}
