1963	async function dispatch(
1964	  req: http.IncomingMessage,
1965	  res: http.ServerResponse,
1966	): Promise<void> {
1967	  res.on('error', () => {
1968	    // 写已销毁套接字等错误无需让进程崩溃
1969	  });
1970	
1971	  const method = String(req.method);
1972	  const target = String(req.url ?? '/'); // 含查询串的原始请求目标
1973	  const pathname = target.split('?')[0]; // 查询串不参与匹配
1974	
1975	  const { outcome, body } = await receiveBody(req, res);
1976	  if (outcome !== 'received') {
1977	    // aborted：未完整接收，不匹配、不预留、不推进任何序列，也不创建记录
1978	    // too-large：已回复 413，不创建记录、不消费序列
1979	    return;
1980	  }
1981	
1982	  // 管理范围：/__contractlab 本身及 /__contractlab/ 前缀。
1983	  // 其中所有请求都不记录、不消费业务序列（含未知子路径的 404）。
1984	  if (pathname === ADMIN_BASE || pathname.startsWith(ADMIN_PREFIX)) {
1985	    await handleAdmin(method, pathname, res);
1986	    return;
1987	  }
1988	
1989	  // 完整接收且不在管理范围：此刻创建记录并取得进程内递增编号。
1990	  // 编号只取决于完整接收顺序，与接口序列的消费位置互不相关。
1991	  const state = activeState;
1992	  const record = requestLog.create({
1993	    method,
1994	    target,
1995	    path: pathname,
1996	    rawHeaders: req.rawHeaders,
1997	    body,
1998	    configVersion: state.version,
1999	  });
2000	  attachDeliveryTracking(res, record.id);
2001	
2002	  // 业务匹配：在本次同步执行内抓取状态快照，预留后与后续 reload 互不影响
2003	  const endpoint =
2004	    method === 'GET' || method === 'POST'
2005	      ? state.endpoints.get(`${method} ${pathname}`)
2006	      : undefined;
2007	
2008	  if (!endpoint) {
2009	    // 未匹配请求：404，不消费、无消费位置
2010	    record.matched = false;
2011	    record.endpoint = `${method} ${pathname}`;
2012	    const planned = buildFrameworkPlanned(
2013	      404,
2014	      state.version,
2015	      'not found\n',
2016	      'text/plain; charset=utf-8',
2017	    );
2018	    record.plannedResponse = planned;
2019	    writePlanned(res, planned, record.id);
2020	    return;
2021	  }
2022	  record.matched = true;
2023	  record.endpoint = endpoint.key;
2024	
2025	  // 正文结构规则（如有）：校验失败返回 400 差异报告，不发送场景响应、不消费序列。
2026	  // 规则、序列与版本均取自上面同一快照 state。
2027	  if (endpoint.bodyRule) {
2028	    const report = validateRequestBody(req, body, endpoint.bodyRule);
2029	    if (report) {
2030	      record.bodyValidationPassed = false;
2031	      record.bodyRejection = report;
2032	      const planned = buildFrameworkPlanned(
2033	        400,
2034	        state.version,
2035	        `${JSON.stringify(report)}\n`,
