163	// ---------------------------------------------------------------------------
164	// 独立临时目录与配置文件：每个用例互不影响，无论成败均清理
165	// ---------------------------------------------------------------------------
166	
167	export async function makeTempDir(t: TestContext): Promise<string> {
168	  const dir = await mkdtemp(path.join(tmpdir(), 'contractlab-test-'));
169	  t.after(() => rm(dir, { recursive: true, force: true }));
170	  return dir;
171	}
