198	// ---------------------------------------------------------------------------
199	// 独立参考实现：按 README 记录的规则语义判断“规则是否接受某 JSON 值”
200	// ---------------------------------------------------------------------------
201	
202	export interface RuleJson {
203	  readonly type: string;
204	  readonly fields?: { readonly [name: string]: RuleJson & { readonly required?: boolean } };
205	  readonly additionalProperties?: boolean;
206	  readonly items?: RuleJson;
207	  readonly required?: boolean;
208	}
209	
210	function isPlainJsonObject(value: unknown): value is Record<string, unknown> {
211	  return typeof value === 'object' && value !== null && !Array.isArray(value);
212	}
213	
214	export function accepts(rule: RuleJson, value: unknown): boolean {
215	  switch (rule.type) {
216	    case 'string':
217	      return typeof value === 'string';
218	    case 'boolean':
219	      return typeof value === 'boolean';
220	    case 'null':
221	      return value === null;
222	    case 'number':
223	      return typeof value === 'number' && Number.isFinite(value);
224	    case 'integer':
225	      return typeof value === 'number' && Number.isInteger(value);
226	    case 'array':
227	      return Array.isArray(value) && value.every((item) => accepts(rule.items as RuleJson, item));
228	    case 'object': {
229	      if (!isPlainJsonObject(value)) {
230	        return false;
231	      }
232	      const fields = rule.fields ?? {};
233	      for (const [name, fieldRule] of Object.entries(fields)) {
234	        const has = Object.prototype.hasOwnProperty.call(value, name);
235	        if (!has) {
236	          if (fieldRule.required === true) {
237	            return false;
238	          }
239	        } else if (!accepts(fieldRule, value[name])) {
240	          return false;
241	        }
242	      }
243	      if (rule.additionalProperties !== true) {
244	        for (const key of Object.keys(value)) {
245	          if (!Object.prototype.hasOwnProperty.call(fields, key)) {
246	            return false;
247	          }
248	        }
249	      }
250	      return true;
251	    }
252	    default:
253	      throw new Error(`参考实现遇到未知规则类型: ${JSON.stringify(rule.type)}`);
254	  }
