1	// OpenAPI 请求正文约定导入（import 子命令）的回归测试
2	//
3	// 覆盖：
4	// - 基本转换：替换 POST 规则、移除无声明 POST 的旧规则、GET 不变、
5	//   保留接口顺序与 responses、additionalProperties 缺省显式输出、特殊字段名保留；
6	// - 本文件内 $ref：共享引用、JSON Pointer 转义、requestBody 级引用，
7	//   以及缺失目标 / 外部引用 / 循环引用（引用链定位）/ 引用节点带额外字段；
8	// - 纯对象 allOf：同名字段递归相交（number∩integer 取 integer）、必填并集、
9	//   各分支额外字段限制（禁止出现的字段被丢弃）、空交集与无法表达的拒绝；
10	// - 操作选择与 requestBody 错误矩阵、schema 错误矩阵；
11	// - 未选中操作与不可达定义不参与转换；
12	// - 成功输出可直接用于真实 serve 与 compare；
13	// - 失败一律退出 2、stderr 可定位（文件 + 操作/定义位置）、stdout 为空。
14	
15	import assert from 'node:assert/strict';
16	import path from 'node:path';
17	import test from 'node:test';
18	import {
19	  makeTempDir,
20	  runCli,
21	  runCompare,
22	  sceneResponse,
23	  SCENE_BODY,
24	  SCENE_STATUS,
25	  sendRequest,
26	  startServer,
27	  writeConfig,
