30	
31	function runImport(openapi: string, config: string) {
32	  return runCli(['import', '--openapi', openapi, '--config', config]);
33	}
34	
35	// 便捷构造：POST 操作的必填 JSON 正文
36	function jsonBody(schema: unknown): unknown {
37	  return { required: true, content: { 'application/json': { schema } } };
38	}
39	
40	function spec(paths: unknown, components?: unknown): unknown {
41	  const doc: Record<string, unknown> = { openapi: '3.0.0', paths };
42	  if (components !== undefined) {
43	    doc.components = components;
44	  }
45	  return doc;
46	}
47	
48	function sceneWith(endpoints: unknown[]): unknown {
49	  return { endpoints };
50	}
51	
52	function postEndpoint(p: string, extra?: Record<string, unknown>): unknown {
53	  return { method: 'POST', path: p, responses: [sceneResponse()], ...extra };
54	}
55	
56	// 解析成功输出：退出码必须为 0，stdout 必须是完整场景 JSON
57	function parseOutput(stdout: string): { endpoints: Record<string, unknown>[] } {
58	  const parsed = JSON.parse(stdout) as { endpoints: Record<string, unknown>[] };
59	  assert.ok(Array.isArray(parsed.endpoints), '输出必须是含 endpoints 数组的场景 JSON');
60	  return parsed;
61	}
